```python
from sage.all import *
from functools import lru_cache
from collections import Counter

p = 1000000007
assert is_prime(p)
K = GF(p)
g, N, W = 25, 12, 11

R = PolynomialRing(K, ["k" + str(i) for i in range(1, N + 1)])
ks = [R(2*g - 2)] + list(R.gens())

@lru_cache(None)
def parts(n, lo=1):
    if n == 0:
        return ((),)
    return tuple(
        (i,) + q
        for i in range(lo, n + 1)
        for q in parts(n - i, i)
    )

@lru_cache(None)
def splits(s):
    """All decompositions of a multiset into two submultisets."""
    items = list(Counter(s).items())
    ans = []

    def go(j, a, b):
        if j == len(items):
            ans.append((tuple(a), tuple(b)))
            return
        x, m = items[j]
        for k in range(m + 1):
            go(j + 1, a + [x]*k, b + [x]*(m-k))

    go(0, [], [])
    return tuple(ans)

sigmas = [
    s
    for w in range(W + 1)
    for s in parts(w)
    if all(x % 3 != 2 for x in s)
]

T = PowerSeriesRing(K, "t", default_prec=N + 1)
t = T.gen()

a = [
    QQ(factorial(6*n)) / factorial(3*n) / factorial(2*n)
    for n in range(N + 1)
]
A = T([K(x) for x in a])
B = T([
    K(a[n] * QQ(6*n + 1) / (6*n - 1))
    for n in range(N + 1)
])
L, D = A.log(), B/A

# E is the positive-t-degree part of -{log(Psi)}_kappa.
E = {}
for s in sigmas:
    if not s:
        cs = L
    else:
        ell = len(s)
        shift = sum(x // 3 for x in s)
        b = sum(x % 3 == 1 for x in s)
        c = (
            QQ((-1)**(ell - 1) * factorial(ell - 1))
            / prod(factorial(m) for m in Counter(s).values())
        )
        cs = K(c) * t**shift * D**b

    for n in range(1, N + 1):
        if cs[n]:
            E[n, s] = -R(cs[n]) * ks[n]

# The t^0 contribution is (1-p_1)^(-kappa_0).
F = {
    (0, (1,)*ell): R(binomial(2*g - 3 + ell, ell))
    for ell in range(W + 1)
}

# If F = exp(E), then n F_n = sum_i i E_i F_(n-i).
for n in range(1, N + 1):
    for s in sigmas:
        z = R.zero()
        for a, b in splits(s):
            for i in range(1, n + 1):
                if (i, a) in E and (n-i, b) in F:
                    z += i * E[i, a] * F[n-i, b]
        if z:
            F[n, s] = z / K(n)

def relation_matrix(degree):
    basis = parts(degree)
    columns = {s: j for j, s in enumerate(basis)}
    rows = []

    for r in range(1, degree + 1):
        for s in sigmas:
            # FZ conditions:
            # 3r >= g+1+|s|, g == r+|s|+1 mod 2.
            if sum(s) > 3*r-g or (g-r-sum(s)-1) % 2:
                continue

            f = F.get((r, s), R.zero())
            if not f:
                continue

            for q in parts(degree-r):
                h = f * prod(ks[x] for x in q)
                row = [K.zero()] * len(basis)
                for exponents, c in h.dict().items():
                    monomial = tuple(
                        i+1
                        for i, m in enumerate(exponents)
                        for _ in range(m)
                    )
                    row[columns[monomial]] = c
                rows.append(row)

    return matrix(K, rows)

M11 = relation_matrix(11)
M12 = relation_matrix(12)

# H(s)[j] sums, over set partitions into j blocks,
# the product of 1/(2*sum(block)+1)!!.
@lru_cache(None)
def H(s):
    if not s:
        return (K.one(),)

    out = [K.zero()] * (len(s) + 1)
    first, tail = s[0], s[1:]
    counts = Counter(tail)

    for block, rest in splits(tail):
        ways = prod(
            binomial(counts[v], m)
            for v, m in Counter(block).items()
        )
        block_sum = first + sum(block)
        denominator = prod(range(1, 2*block_sum + 2, 2))
        factor = K(ways) / K(denominator)

        for j, c in enumerate(H(rest)):
            out[j+1] += factor*c

    return tuple(out)

@lru_cache(None)
def intersection(s):
    # A common nonzero normalization has been omitted.
    # Inclusion-exclusion converts kappa products to psi integrals.
    return sum(
        (-1)**(len(s)-j) * K(factorial(2*g-3+j)) * c
        for j, c in enumerate(H(s))
    )

P = matrix(K, [
    [intersection(tuple(sorted(a+b))) for b in parts(12)]
    for a in parts(11)
])

print("degree 11 relations:", M11.dimensions(), M11.rank())
print("degree 12 relations:", M12.dimensions(), M12.rank())
print("socle pairing:", P.dimensions(), P.rank())
print("relations annihilate pairing:",
      (M12 * P.transpose()).is_zero())

assert len(parts(12)) == 77
assert M11.rank() == 13
assert M12.rank() == 33
assert P.rank() == 43
assert (M12 * P.transpose()).is_zero()
